import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.DfDAiEgj.js";const w=JSON.parse('{"title":"法律","description":"","frontmatter":{},"headers":[],"relativePath":"data-dive/law.md","filePath":"data-dive/law.md","lastUpdated":null}'),p={name:"data-dive/law.md"};function n(d,a,c,i,l,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="法律" tabindex="-1">法律 <a class="header-anchor" href="#法律" aria-label="Permalink to &quot;法律&quot;">​</a></h1><p>网络安全法</p><p>国家安全法</p><p>专利：<a href="https://www.cnipa.gov.cn/module/download/downfile.jsp?classid=0&amp;showname=1.%E4%B8%93%E5%88%A9%E7%BA%A0%E7%BA%B7%E8%A1%8C%E6%94%BF%E8%B0%83%E8%A7%A3%E5%8A%9E%E6%A1%88%E6%8C%87%E5%8D%97.doc&amp;filename=2e3658bda3c744f98585347c015fcb99.doc" target="_blank" rel="noreferrer">https://www.cnipa.gov.cn/module/download/downfile.jsp?classid=0&amp;showname=1.专利纠纷行政调解办案指南.doc&amp;filename=2e3658bda3c744f98585347c015fcb99.doc</a></p><p>《专利法》第六条 执行本单位的任务或者主要是利用本单位的物质技术条件所完成的发明创造为职务发明创造。职务发明创造申请专利的权利属于该单位；申请被批准后，该单位为专利权人。</p><p>非职务发明创造，申请专利的权利属于发明人或者设计人；申请被批准后，该发明人或者设计人为专利权人。</p><p>利用本单位的物质技术条件所完成的发明创造，单位与发明人或者设计人订有合同，对申请专利的权利和专利权的归属作出约定的，从其约定。</p><p><a href="https://zhuanli.tianyancha.com/" target="_blank" rel="noreferrer">https://zhuanli.tianyancha.com/</a></p><p>著作权：<a href="https://www.zhihu.com/topic/19633255/index" target="_blank" rel="noreferrer">https://www.zhihu.com/topic/19633255/index</a></p><p>个人信息保护法： <a href="https://www.bilibili.com/video/BV1d3411b76J?spm_id_from=333.851.b_7265636f6d6d656e64.1" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1d3411b76J?spm_id_from=333.851.b_7265636f6d6d656e64.1</a></p><p>国家互联网信息办公室关于《网络数据安全管理条例（征求意见稿）》公开征求意见的通知:<a href="http://www.cac.gov.cn/2021-11/14/c_1638501991577898.htm" target="_blank" rel="noreferrer">http://www.cac.gov.cn/2021-11/14/c_1638501991577898.htm</a></p>',11)])])}const _=e(p,[["render",n]]);export{w as __pageData,_ as default};
